use std::{error::Error, fs, path::Path};
use tablecraft_testkit::fixtures::access::canonical_catalog_names::rename_pair;

const DESTINATION: &str = ".cache/rename-sdk-20261108";

fn main() -> Result<(), Box<dyn Error>> {
    let destination = Path::new(DESTINATION);
    fs::create_dir(destination)?;
    let boundary = "表".repeat(64);
    let cases = [
        ("Items", "Renamed", true),
        ("LongerSource", "I", true),
        ("Items", "雪 Customers", true),
        ("Items", "items", false),
        ("\u{feff}雪🙂", "\u{feff}āΩ雪🙂A", true),
        ("Items", "Items", false),
        ("Items", boundary.as_str(), true),
    ];

    for header in [5, 6] {
        for (index, (old_name, new_name, populated)) in cases.iter().enumerate() {
            let pair = rename_pair(header, old_name, new_name, *populated);
            let prefix = format!("header-{header}-case-{index:02}");
            fs::write(destination.join(format!("{prefix}-before.accdb")), pair.before)?;
            fs::write(destination.join(format!("{prefix}-after.accdb")), pair.after)?;
            fs::write(destination.join(format!("{prefix}-old.txt")), pair.old_name)?;
            fs::write(destination.join(format!("{prefix}-new.txt")), pair.new_name)?;
            fs::write(
                destination.join(format!("{prefix}-rows.txt")),
                pair.rows.len().to_string(),
            )?;
        }
    }

    println!("Exported 14 independent raw BEFORE/AFTER pairs");
    Ok(())
}
